/bin/zsh -lc "python -c 'import csv,json,math; from pathlib import Path
with open(\"counts.tsv\",newline=\"\") as f:
 reader=csv.reader(f,delimiter=\"\\t\"); header=next(reader); rows=list(reader)
assert header[0]==\".\"
counts={r[0]:[int(x) for x in r[1:]] for r in rows}
assert len(counts)==len(rows)
assert all(len(v)==len(header)-1 and all(x>=0 for x in v) and sum(v)>0 for v in counts.values())
with open(\"samples.csv\",newline=\"\") as f: samples=list(csv.DictReader(f))
assert len({r[\"sample_id\"] for r in samples})==len(samples)
assert set(counts)=={r[\"sample_id\"] for r in samples}
groups={\"reef\":[],\"lagoon\":[]}
for sample in samples:
 values=counts[sample[\"sample_id\"]]; total=sum(values)
 h=-math.fsum((x/total)*math.log(x/total) for x in values if x>0)
 groups[sample[\"facies\"]].append(h)
 print(sample[\"sample_id\"],sample[\"facies\"],repr(h))
results={\"mean_shannon_\"+facies:math.fsum(hs)/len(hs) for facies,hs in groups.items()}
answer={\"status\":\"completed\",\"results\":results,\"assumptions\":[],\"exclusions\":[],\"issues\":[],\"summary\":\"Matched all eight samples to facies by sample_id. Calculated each sample Shannon diversity as -sum(p * ln(p)) using genus specimen-count proportions, with zero counts contributing zero, then computed the arithmetic mean across the four samples in each facies.\"}
Path(\"answer.json\").write_text(json.dumps(answer,indent=2,allow_nan=False)+\"\\n\")
schema=json.loads(Path(\"answer.schema.json\").read_text())
assert set(answer)==set(schema[\"required\"])
assert set(results)=={\"mean_shannon_reef\",\"mean_shannon_lagoon\"}
try: import jsonschema
except ImportError: pass
else: jsonschema.validate(answer,schema)
print(json.dumps(answer,indent=2))'"

